    ensures valid(always(p.and(q)).implies(always(p).and(always(q)))),
{
    // Expand the definitions of `always` / `and` and use distribution of `forall` over `&&`.
    assert(
        forall |ex: Execution<T>|
            always(p.and(q)).satisfied_by(ex)
            ==> (
                (forall |i: nat| #[trigger] p.satisfied_by(ex.suffix(i)))
                &&
                (forall |i: nat| #[trigger] q.satisfied_by(ex.suffix(i)))
            )
    );
}

